})
export class CalendarComponent implements OnInit {
  calendarItems$!: Observable<CalendarItem[]>;
  stats$!: Observable<CalendarStats>;
  activeFilter: 'all' | 'assessments' | 'certifications' = 'all';
  viewMode: 'timeline' | 'calendar' = 'timeline';

  currentDate: Date = new Date();
  calendarDays: CalendarDay[] = [];
  weekDays: string[] = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  allItems: CalendarItem[] = [];

  constructor(
    private calendarService: CalendarDataService,
    private dialog: MatDialog
  ) {}

  ngOnInit(): void {
    this.loadData();
    this.generateCalendar();
  }

  loadData(): void {
    this.calendarItems$ = this.calendarService.getFilteredItems$(this.activeFilter);
    this.stats$ = this.calendarService.getCalendarStats$();

    this.calendarService.getAllCalendarItems$().subscribe((items: CalendarItem[]) => {
      this.allItems = items;
      this.generateCalendar();
    });
  }

  setFilter(filter: 'all' | 'assessments' | 'certifications'): void {
    this.activeFilter = filter;
    this.loadData();
    if (this.viewMode === 'calendar') {
      this.generateCalendar();
    }
  }

  setViewMode(mode: 'timeline' | 'calendar'): void {
    this.viewMode = mode;
    if (mode === 'calendar') {
      this.generateCalendar();
    }
  }

  generateCalendar(): void {
    const year = this.currentDate.getFullYear();
    const month = this.currentDate.getMonth();

    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const prevMonthLastDay = new Date(year, month, 0);

    const firstDayOfWeek = firstDay.getDay();
    const daysInMonth = lastDay.getDate();
    const daysInPrevMonth = prevMonthLastDay.getDate();

    this.calendarDays = [];

    for (let i = firstDayOfWeek - 1; i >= 0; i--) {
      const date = new Date(year, month - 1, daysInPrevMonth - i);
      this.calendarDays.push({
        date,
        dayNumber: daysInPrevMonth - i,
        isCurrentMonth: false,
        isToday: this.isToday(date),
        items: this.getItemsForDate(date)
      });
    }

    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(year, month, day);
      this.calendarDays.push({
        date,
        dayNumber: day,
        isCurrentMonth: true,
        isToday: this.isToday(date),
        items: this.getItemsForDate(date)
      });
    }

    const remainingDays = 42 - this.calendarDays.length;
    for (let day = 1; day <= remainingDays; day++) {
      const date = new Date(year, month + 1, day);
      this.calendarDays.push({
        date,
        dayNumber: day,
        isCurrentMonth: false,
        isToday: this.isToday(date),
        items: this.getItemsForDate(date)
      });
    }
  }

  getItemsForDate(date: Date): CalendarItem[] {
    let filteredItems = this.allItems;

    if (this.activeFilter === 'assessments') {
      filteredItems = this.allItems.filter(item => item.type === 'assessment');
    } else if (this.activeFilter === 'certifications') {
      filteredItems = this.allItems.filter(item => item.type === 'certification');
    }

    return filteredItems.filter(item => {
      const itemDate = new Date(item.date);
      return itemDate.getDate() === date.getDate() &&
             itemDate.getMonth() === date.getMonth() &&
             itemDate.getFullYear() === date.getFullYear();
    });
  }

  isToday(date: Date): boolean {
    const today = new Date();
    return date.getDate() === today.getDate() &&
           date.getMonth() === today.getMonth() &&
           date.getFullYear() === today.getFullYear();
  }

  previousMonth(): void {
    this.currentDate = new Date(
      this.currentDate.getFullYear(),
      this.currentDate.getMonth() - 1,
      1
    );
    this.generateCalendar();
  }

  nextMonth(): void {
    this.currentDate = new Date(
      this.currentDate.getFullYear(),
      this.currentDate.getMonth() + 1,
      1
    );
    this.generateCalendar();
  }

  getCurrentMonthYear(): string {
    return new Intl.DateTimeFormat('en-US', { 
      month: 'long', 
      year: 'numeric' 
    }).format(this.currentDate);
  }

  getStatusClass(status: string): string {
    const statusMap: { [key: string]: string } = {
      'assigned': 'bg-blue-500',
      'completed': 'bg-green-500',
      'in_progress': 'bg-yellow-500',
      'upcoming': 'bg-purple-500'
    };
    return statusMap[status] || 'bg-gray-500';
  }

  getStatusText(status: string): string {
    const statusTextMap: { [key: string]: string } = {
      'assigned': 'Assigned',
      'completed': 'Completed',
      'in_progress': 'In Progress',
      'upcoming': 'Upcoming'
    };
    return statusTextMap[status] || status;
  }

  formatDate(date: Date): string {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    }).format(new Date(date));
  }

  getDayOfWeek(date: Date): string {
    return new Intl.DateTimeFormat('en-US', { weekday: 'long' }).format(new Date(date));
  }

  trackByItemId(index: number, item: CalendarItem): string {
    return item.id;
  }

  openSubmissionDialog(item: CalendarItem): void {
    if (item.isCompleted) {
      return;
    }

    const dialogRef = this.dialog.open(FormSubmissionDialogComponent, {
      width: '600px',
      maxWidth: '90vw',
      data: { item },
      disableClose: false,
      hasBackdrop: true,
      backdropClass: 'dialog-backdrop',
      panelClass: 'submission-dialog-panel',
      autoFocus: true,
      restoreFocus: true,
      position: {
        top: '50px'
      }
    });

    dialogRef.afterClosed().subscribe((result: SubmissionResult | undefined) => {
      if (result) {
        this.calendarService.markCompleted(item.id, {
          score: result.score,
          attachments: result.attachments,
          submissionNotes: result.submissionNotes
        });
      }
    });
  }
}

