  email = '';
  password = '';
  role: 'admin' | 'employee' = 'employee';
  employeeId = '';
  department = '';
  designation = '';

  errorMessage = '';
  isLoading = false;

  constructor(private authService: AuthService) {}

  togglePasswordVisibility() {
    this.showPassword = !this.showPassword;
