import { CommonModule } from '@angular/common';
import {
  Component,
  Input,
  ElementRef,
  ViewChild,
  TemplateRef,
} from '@angular/core';
import { createPopper, Instance } from '@popperjs/core';


@Component({
  selector: 'app-table-dropdown',
  imports: [CommonModule],
  templateUrl: './table-dropdown.component.html',
  styles: ``
})
export class TableDropdownComponent {

  @Input() dropdownButton: any;
  @Input() dropdownContent: any;
  @ViewChild('buttonRef') buttonRef!: ElementRef<HTMLDivElement>;
  @ViewChild('contentRef') contentRef!: ElementRef<HTMLDivElement>;

  isOpen = false;
  private popperInstance: Instance | null = null;

  constructor() {}

  ngAfterViewInit() {
    document.addEventListener('click', this.close.bind(this));

    if (this.buttonRef && this.contentRef) {
      this.popperInstance = createPopper(
        this.buttonRef.nativeElement,
        this.contentRef.nativeElement,
        {
          placement: 'bottom-end',
          modifiers: [
            {
              name: 'offset',
              options: {
                offset: [0, 4],
              },
            },
          ],
        }
      );
    }
  }

  ngOnDestroy() {
    document.removeEventListener('click', this.close.bind(this));
    if (this.popperInstance) {
      this.popperInstance.destroy();
      this.popperInstance = null;
    }
  }

  toggle() {
    this.isOpen = !this.isOpen;
    if (this.popperInstance) {
      this.popperInstance.update();
    }
  }

  close(event: MouseEvent) {
    const target = event.target as Node;
    if (this.buttonRef && this.contentRef) {
      const dropdown = this.buttonRef.nativeElement.closest('div');
      if (dropdown && !dropdown.contains(target)) {
        this.isOpen = false;
      }
    }
  }
}

import { CommonModule } from '@angular/common';
import { Component, Input } from '@angular/core';

@Component({
  selector: 'app-countdown-timer',
  imports: [
    CommonModule,
  ],
  templateUrl: './countdown-timer.component.html',
  styles: ``
})
export class CountdownTimerComponent {

  @Input() targetDate!: Date;

  timeLeft = {
    days: 0,
    hours: 0,
    minutes: 0,
    seconds: 0,
  };

  private intervalId: any;

  ngOnInit(): void {
    this.startCountdown();
  }

  ngOnDestroy(): void {
    clearInterval(this.intervalId);
  }

  startCountdown(): void {
    this.intervalId = setInterval(() => {
      const now = new Date();
      const difference = this.targetDate.getTime() - now.getTime();

      if (difference > 0) {
        this.timeLeft.days = Math.floor(difference / (1000 * 60 * 60 * 24));
        this.timeLeft.hours = Math.floor((difference / (1000 * 60 * 60)) % 24);
        this.timeLeft.minutes = Math.floor((difference / (1000 * 60)) % 60);
        this.timeLeft.seconds = Math.floor((difference / 1000) % 60);
      } else {
        clearInterval(this.intervalId);
      }
    }, 1000);
  }

  formatTime(value: number): string {
    return value.toString().padStart(2, '0');
  }
}

